/*
 * W0-T12 acceptance check 4: the table generator reproduces the committed table (ARCHITECTURE §5.1: tables that need a
 * transcendental function are generated by a script under scripts/tables/, committed as integers, and re-checked by CI).
 *
 *   - The generator's text is the committed file's bytes, and its integers are the ones packages/sim/core exports.
 *   - The integers are right: each is within one unit of the bin mean that numerical integration of −ln(1 − u) gives, by a method
 *     that shares neither the antiderivative nor the rounding with the generator.
 *   - The generator's refusal to write a table whose roundings depend on the platform's libm is exercised on inputs that are close
 *     to a tie, so it is known to fire.
 *   - The command line writes, checks and fails as the header of the script says.
 */
import { afterAll, describe, expect, test } from 'bun:test'
import { spawnSync } from 'node:child_process'
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { EXP_BINS, EXP_QUANTILES, EXP_SCALE, sum } from '../../packages/sim/core'
import { BINS, MARGIN, SCALE, TABLE_FILE, checkTable, computeTable, expectedSource, renderTable, roundToTotal } from '../../scripts/tables/exp-quantiles'

const root = path.resolve(import.meta.dirname, '../..')
const committed = readFileSync(path.join(root, TABLE_FILE), 'utf8')

describe('the committed exponential table', () => {
  test('is exactly what the generator writes', () => {
    expect(expectedSource()).toBe(committed)
    expect(checkTable(root)).toBeNull()
  })

  test('holds the generator\'s integers, which packages/sim/core exports under the generator\'s constants', () => {
    const { values } = computeTable()
    expect([BINS, SCALE]).toEqual([EXP_BINS, EXP_SCALE])
    expect(values).toEqual([...EXP_QUANTILES])
    expect(sum(values)).toBe(BINS * SCALE)
  })

  test('is a generated file that says so, and is plain integers', () => {
    expect(committed.startsWith('// GENERATED by `bun scripts/tables/exp-quantiles.ts --write`')).toBe(true)
    const start = committed.indexOf('= [') + 2
    const body = committed.slice(start, committed.lastIndexOf(']') + 1)
    expect(body).toMatch(/^\[(\s*\d+,)+\s*\]$/)
    expect(committed.match(/export const /g)).toHaveLength(3)
    expect(committed.split('\n').filter((line) => !line.startsWith('//')).join('\n')).not.toMatch(/Math\./)
    expect(renderTable(computeTable().values)).toBe(committed)
  })

  test('has integers within one unit of each bin\'s mean, by composite Simpson integration of the quantile function', () => {
    // m_k = BINS · ∫ −ln(1 − u) du over [k/BINS, (k+1)/BINS), in units of 1/SCALE. The last bin has a singularity at u = 1, and its
    // integral is the closed form (1 + ln BINS) / BINS · BINS.
    const quantile = (u: number) => -Math.log(1 - u)
    const simpson = (a: number, b: number, intervals: number) => {
      const h = (b - a) / intervals
      let total = quantile(a) + quantile(b)
      for (let i = 1; i < intervals; i++) total += quantile(a + i * h) * (i % 2 === 1 ? 4 : 2)
      return (total * h) / 3
    }
    for (let k = 0; k < BINS - 1; k++) {
      const exact = BINS * simpson(k / BINS, (k + 1) / BINS, 400) * SCALE
      expect(Math.abs(EXP_QUANTILES[k] - exact), `entry ${k}`).toBeLessThan(1)
    }
    expect(Math.abs(EXP_QUANTILES[BINS - 1] - (1 + Math.log(BINS)) * SCALE)).toBeLessThan(1)
  })

  test('was rounded with room to spare: the least distance from a computed value to a rounding decision is far above the margin', () => {
    const { margin } = computeTable()
    expect(margin).toBeGreaterThanOrEqual(MARGIN)
    expect(margin).toBeGreaterThan(10 * MARGIN) // observed 3.4e-4 of a unit [measured 2026-11-04]; a libm error is about 1e-7 [estimated]
  })
})

describe('roundToTotal', () => {
  test('floors, then gives the extra units to the largest fractions, so the total is exact', () => {
    const { values, margin } = roundToTotal([1.25, 2.5, 3.25], 7)
    expect(values).toEqual([1, 3, 3])
    expect(margin).toBe(0.25)
    expect(roundToTotal([0.9, 0.4, 0.7], 2).values).toEqual([1, 0, 1])
    expect(roundToTotal([1.4, 1.6], 3).values).toEqual([1, 2])
  })

  test('refuses a value within MARGIN of an integer, since a different libm could floor it the other way', () => {
    expect(() => roundToTotal([1.000001, 1.999999], 3)).toThrow(/libm/)
    expect(() => roundToTotal([1.0000005, 1.9999995], 3)).toThrow(/libm/)
    // An exact integer is refused too: 3 could be computed as 2.9999999999999996 elsewhere, and floored to 2.
    expect(() => roundToTotal([2, 3, 4], 9)).toThrow(/libm/)
    expect(() => roundToTotal([1.4, 1.6], 3)).not.toThrow()
  })

  test('refuses a tie at the cut, where which entry gets the unit would be an accident of the platform', () => {
    expect(() => roundToTotal([1.5, 1.5], 3)).toThrow(/libm/)
    expect(() => roundToTotal([1.5, 1.5000001], 3)).toThrow(/libm/)
    expect(() => roundToTotal([1.5, 1.6], 3)).not.toThrow()
  })

  test('refuses inputs whose sum is not the total: a deficit that is negative, or larger than the number of entries', () => {
    expect(() => roundToTotal([1.25, 1.25], 1)).toThrow(/miss the total by -1/)
    expect(() => roundToTotal([1.25, 1.25], 5)).toThrow(/miss the total by 3/)
  })

  test('hands the extra units to equal fractions in index order when the cut falls between groups of them', () => {
    // Fractions .75 (entries 1 and 3) and .25 (entries 0 and 2): the two units go to the .75s.
    expect(roundToTotal([1.25, 1.75, 1.25, 1.75], 6).values).toEqual([1, 2, 1, 2])
    // Equal fractions across the cut would make the choice an accident of the sort, so they are refused above; below the cut, order is free.
    expect(roundToTotal([1.75, 1.75, 1.5], 5).values).toEqual([2, 2, 1])
  })
})

describe('bun scripts/tables/exp-quantiles.ts', () => {
  const scratch: string[] = []
  afterAll(() => scratch.forEach((dir) => rmSync(dir, { recursive: true, force: true })))
  const tree = (): string => {
    const dir = mkdtempSync(path.join(tmpdir(), 'enginespace-table-'))
    scratch.push(dir)
    mkdirSync(path.join(dir, 'packages/sim/core'), { recursive: true })
    return dir
  }
  const run = (...args: string[]) => {
    const result = spawnSync(process.execPath, [path.join(root, 'scripts/tables/exp-quantiles.ts'), ...args], { cwd: root, encoding: 'utf8' })
    return { status: result.status, stdout: result.stdout, stderr: result.stderr }
  }

  test('--check passes on the repository', () => {
    const result = run('--check')
    expect(result.stderr).toBe('')
    expect(result.status).toBe(0)
    expect(result.stdout).toContain('is what the generator writes (1024 entries)')
  })

  test('--write writes the committed bytes into the tree it is given, and --check then passes there', () => {
    const dir = tree()
    expect(run('--check', '--root', dir).status).toBe(1)
    expect(run('--write', '--root', dir).status).toBe(0)
    expect(readFileSync(path.join(dir, TABLE_FILE), 'utf8')).toBe(committed)
    expect(run('--check', '--root', dir).status).toBe(0)
  })

  test('--check fails on a table that has changed by one unit, and says where', () => {
    const dir = tree()
    writeFileSync(path.join(dir, TABLE_FILE), committed.replace('32, 96, 160, 224', '32, 96, 160, 225'))
    const result = run('--check', '--root', dir)
    expect(result.status).toBe(1)
    expect(result.stderr).toContain('is not what the generator writes (first difference on line 16)')
    expect(result.stderr).toContain('--write')
  })

  test('--check fails on a missing table and exits 2 with the usage on no mode or a bad argument', () => {
    const missing = run('--check', '--root', tree())
    expect(missing.status).toBe(1)
    expect(missing.stderr).toContain('is missing')
    for (const args of [[], ['--nope'], ['--root']]) {
      const result = run(...args)
      expect(result.status, args.join(' ')).toBe(2)
      expect(result.stderr).toContain('usage: bun scripts/tables/exp-quantiles.ts')
    }
  })
})
